import{_ as s,o as a,c as t,a5 as e}from"./chunks/framework.BEZBAInb.js";const g=JSON.parse('{"title":"문법 하이라이터","description":"","frontmatter":{"title":"문법 하이라이터","order":5},"headers":[],"relativePath":"ko/2.4/tutorial/core/ks-editor-highlighter.md","filePath":"ko/2.4/tutorial/core/ks-editor-highlighter.md","lastUpdated":1788455378000}'),h={name:"ko/2.4/tutorial/core/ks-editor-highlighter.md"};function l(n,i,p,r,d,o){return a(),t("div",null,[...i[0]||(i[0]=[e(`<h1 id="knd-kshighlighter-에디터-문법-하이라이트" tabindex="-1">KND_KsHighlighter 에디터 문법 하이라이트 <a class="header-anchor" href="#knd-kshighlighter-에디터-문법-하이라이트" aria-label="Permalink to &quot;KND_KsHighlighter 에디터 문법 하이라이트&quot;">​</a></h1><h2 id="머리말" tabindex="-1">머리말 <a class="header-anchor" href="#머리말" aria-label="Permalink to &quot;머리말&quot;">​</a></h2><p>문법 하이라이트는 에디터의 중요한 구성 요소입니다. 개발자가 코드 구조를 직관적으로 식별하도록 도와 작성 효율과 가독성을 높입니다.<br><code>KND_KsHighlighter</code>는 Godot 엔진의 <code>SyntaxHighlighter</code>를 기반으로 구현된 하이라이터이며 KS 스크립트 전용입니다. 하이라이트 규칙을 하나의 스크립트에 집중 정의하여 사용자 지정과 확장이 매우 유연합니다. 기존 규칙을 쉽게 조정할 수 있고 완전히 새로운 색상方案도 추가할 수 있습니다.</p><h2 id="기본-구현" tabindex="-1">기본 구현 <a class="header-anchor" href="#기본-구현" aria-label="Permalink to &quot;기본 구현&quot;">​</a></h2><p><code>KND_KsHighlighter</code>에서 하이라이트 규칙은 배열로 저장됩니다. 각 배열 요소는 두 개의 키를 가진 딕셔너리입니다.</p><ul><li><code>regex</code>: 텍스트를 매칭하는 정규식(Godot RegEx 문법).</li><li><code>color</code>: 매칭된 텍스트의 색상. <code>Color(r, g, b, a)</code>로 표현하며, <code>a</code>는 투명도입니다(선택, 기본값 1.0).</li></ul><p>예시 구조:</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">	&quot;regex&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">b(if|else|endif)</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">b&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">	&quot;color&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>하이라이터는 배열 순서대로 규칙을 매칭합니다. 나중에 적용된 규칙이 이전 매칭을 덮어쓸 수 있으므로 규칙 순서가 매우 중요합니다. 일반 명령은 앞에, 문자열과 주석은 뒤에 두어 덮어쓰기 효과가 합리적으로 작동하도록 하는 것을 권장합니다.</p><h2 id="사용자-지정-색상方案" tabindex="-1">사용자 지정 색상方案 <a class="header-anchor" href="#사용자-지정-색상方案" aria-label="Permalink to &quot;사용자 지정 색상方案&quot;">​</a></h2><p>에디터에 사용자 지정 하이라이트를 적용하는 방법은 두 가지입니다.</p><h3 id="방법-1-리소스-파일-수정-권장" tabindex="-1">방법 1: 리소스 파일 수정(권장) <a class="header-anchor" href="#방법-1-리소스-파일-수정-권장" aria-label="Permalink to &quot;방법 1: 리소스 파일 수정(권장)&quot;">​</a></h3><p>기본 색상方案은 리소스 파일 형태로 다음 위치에 저장됩니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>res://addons/konado/editor/ks_editor/ks_syntax_highlighter.tres</span></span></code></pre></div><p>이 리소스 파일을 직접 편집하면 수정 사항을 유지할 수 있고 매번 다시 생성할 필요가 없습니다.<br> 코드에서 이 리소스를 로드해 사용합니다.</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set_syntax_highlighter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">load</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;res://addons/konado/editor/ks_editor/ks_syntax_highlighter.tres&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><h3 id="방법-2-인스턴스-동적-생성" tabindex="-1">방법 2: 인스턴스 동적 생성 <a class="header-anchor" href="#방법-2-인스턴스-동적-생성" aria-label="Permalink to &quot;방법 2: 인스턴스 동적 생성&quot;">​</a></h3><p>코드에서 새 <code>KND_KsHighlighter</code> 인스턴스를 직접 만들고 사용자 지정 규칙을 설정할 수도 있습니다. 예를 들어 스크립트의 <code>highlight_rules</code>를 수정합니다.</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set_syntax_highlighter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">KND_KsHighlighter</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())</span></span></code></pre></div><blockquote><p><strong>주의</strong>: <code>KND_KsHighlighter.gd</code> 스크립트를 직접 수정한 경우 변경 사항을 적용하려면 리소스 파일을 다시 생성해야 할 수 있습니다. 색상 관리를 더 명확하게 하기 위해 리소스 파일 방식을 우선 사용하는 것을 권장합니다.</p></blockquote>`,20)])])}const c=s(h,[["render",l]]);export{g as __pageData,c as default};
